frappe.ui.form.on('Customer', {
    setup: function(frm) {
        // Filter Membership Plans by the selected Customer Group
        frm.set_query("custom_membership_plan", function() {
            if (frm.doc.customer_group) return { filters: { "custom_customer_group": frm.doc.customer_group } };
        });
        
        // Filter Parent Institution to only show Institutional Members
        frm.set_query("custom_parent_institution", function() {
            return { filters: { "customer_group": "Institutional Member" } };
        });
    },

    customer_group: function(frm) {
        // Only automate these settings for new records
        if (!frm.is_new() || !frm.doc.customer_group) return;

        // Reset dependent fields on group change
        frm.set_value('custom_membership_plan', '');
        frm.set_value('custom_membership_expiry_date', '');
        frm.set_value('custom_membership_start_date', '');
        frm.set_value('custom_original_join_date', '');
        frm.set_value('custom_parent_institution', '');

        // --- PRICE LIST LOGIC ---
        const railway_groups = ['Railway Life Member', 'Railway Non Life Member'];
        if (railway_groups.includes(frm.doc.customer_group)) {
            frm.set_value('default_price_list', 'Railway Member Rate');
        } else {
            frm.set_value('default_price_list', 'Non-Railway Member Rate');
        }

        // --- NAMING SERIES LOGIC ---
        let series = '';
        let is_member = 1; 
        
        switch(frm.doc.customer_group) {
            case 'Railway Life Member':
            case 'Railway Non Life Member': series = '3####'; break;
            case 'Other Government Officer': series = '4####'; break;
            case 'Railway Ward Member': series = '5####'; break;
            case 'Private Member': series = '7####'; break;
            case 'Institutional Member': series = '9####'; break;
            case 'Institutional Nominee': series = ''; break; 
            case 'Non Member': series = '8####'; is_member = 0; break;
            default: series = 'CUST-.YYYY.-.####'; is_member = 0;
        }

        if (series) frm.set_value('naming_series', series);

        // --- UI VISIBILITY & READ-ONLY LOGIC ---
        if (is_member === 1) {
            frm.set_df_property('custom_membership_plan', 'hidden', 0);
            frm.set_df_property('custom_membership_plan', 'reqd', 1);
            frm.set_df_property('custom_membership_start_date', 'hidden', 0);
            frm.set_df_property('custom_membership_start_date', 'reqd', 1);

            let is_nominee = (frm.doc.customer_group === 'Institutional Nominee');
            frm.set_df_property('custom_membership_plan', 'read_only', is_nominee);
            frm.set_df_property('custom_membership_start_date', 'read_only', is_nominee);
            frm.set_df_property('custom_membership_expiry_date', 'read_only', is_nominee);
            // Original Join Date is usually permanent after first save
            frm.set_df_property('custom_original_join_date', 'read_only', is_nominee);
        } else {
            frm.set_df_property('custom_membership_plan', 'hidden', 1);
            frm.set_df_property('custom_membership_plan', 'reqd', 0);
            frm.set_df_property('custom_membership_start_date', 'hidden', 1);
            frm.set_df_property('custom_membership_start_date', 'reqd', 0);
            frm.set_df_property('custom_membership_expiry_date', 'hidden', 1);
            frm.set_df_property('custom_membership_expiry_date', 'reqd', 0);
        }
    },

    custom_parent_institution: function(frm) {
        if (!frm.is_new()) return;

        if (frm.doc.customer_group === 'Institutional Nominee' && frm.doc.custom_parent_institution) {
            frappe.call({
                method: 'frappe.client.get',
                args: { doctype: 'Customer', name: frm.doc.custom_parent_institution },
                callback: function(parent_r) {
                    let parent_plan = parent_r.message.custom_membership_plan;
                    let parent_start = parent_r.message.custom_membership_start_date;
                    let parent_expiry = parent_r.message.custom_membership_expiry_date;
                    
                    if (!parent_plan) {
                        frappe.msgprint({
                            title: 'Error', 
                            indicator: 'red', 
                            message: 'The selected Parent Institution does not have an active Membership Plan.'
                        });
                        frm.set_value('custom_parent_institution', '');
                        return;
                    }

                    // Inherit Plan and Dates from Parent
                    frm.set_value('custom_membership_plan', parent_plan);
                    if (parent_start) {
                        frm.set_value('custom_membership_start_date', parent_start);
                        // SET ORIGINAL JOIN DATE FOR NOMINEE
                        frm.set_value('custom_original_join_date', parent_start);
                    }
                    if (parent_expiry) {
                        frm.set_value('custom_membership_expiry_date', parent_expiry);
                        frm.set_df_property('custom_membership_expiry_date', 'hidden', 0);
                    }

                    // Check Nominee Limits
                    frappe.db.get_value('Item', parent_plan, 'custom_allowed_nominees').then(item_r => {
                        let max_limit = item_r.message.custom_allowed_nominees || 0;
                        frappe.call({
                            method: 'frappe.client.get_list',
                            args: {
                                doctype: 'Customer',
                                filters: {
                                    'custom_parent_institution': frm.doc.custom_parent_institution,
                                    'disabled': 0, 
                                    'name': ['!=', frm.doc.name] 
                                },
                                fields: ['name']
                            },
                            callback: function(list_r) {
                                let active_nominees = list_r.message || [];
                                if (active_nominees.length >= max_limit) {
                                    frappe.msgprint({
                                        title: 'Limit Reached', 
                                        indicator: 'red', 
                                        message: `This institution has reached its limit of <b>${max_limit} active nominees</b>.`
                                    });
                                    frm.set_value('custom_parent_institution', '');
                                    frm.set_value('naming_series', '');
                                    return;
                                }
                                // REMOVED DOT FROM NOMINEE ID LOGIC
                                let new_id = frm.doc.custom_parent_institution + '-#';
                                frm.set_value('naming_series', new_id);
                            }
                        });
                    });
                }
            });
        }
    },

    custom_membership_plan: function(frm) {
        if (!frm.is_new() || frm.doc.customer_group === 'Institutional Nominee') return;

        if (frm.doc.custom_membership_plan) {
            frappe.db.get_value('Item', frm.doc.custom_membership_plan, 'custom_validity_in_years').then(r => {
                let years = r.message.custom_validity_in_years || 0;
                if (years > 0) {
                    let start_date = frm.doc.custom_membership_start_date || frappe.datetime.get_today();
                    let expiry_date = frappe.datetime.add_days(frappe.datetime.add_months(start_date, years * 12), -1);
                    
                    frm.set_value('custom_membership_expiry_date', expiry_date);
                    
                    if (!frm.doc.custom_membership_start_date) {
                        frm.set_value('custom_membership_start_date', start_date);
                        // INITIALIZE ORIGINAL JOIN DATE
                        frm.set_value('custom_original_join_date', start_date);
                    }
                    
                    frm.set_df_property('custom_membership_expiry_date', 'hidden', 0);
                    frm.set_df_property('custom_membership_expiry_date', 'reqd', 1);
                } else {
                    frm.set_value('custom_membership_expiry_date', '');
                    frm.set_df_property('custom_membership_expiry_date', 'hidden', 1);
                }
            });
        }
    },

    custom_membership_start_date: function(frm) {
        if (!frm.is_new() || frm.doc.customer_group === 'Institutional Nominee') return;

        // SYNC ORIGINAL JOIN DATE IF START DATE CHANGES ON NEW RECORD
        if (frm.doc.custom_membership_start_date) {
            frm.set_value('custom_original_join_date', frm.doc.custom_membership_start_date);
        }

        if (frm.doc.custom_membership_plan) frm.trigger('custom_membership_plan');
    },

    refresh: function(frm) {
        if (frm.doc.customer_group === 'Institutional Nominee' && !frm.doc.disabled && !frm.is_new()) {
            frm.add_custom_button(__('Retire Nominee'), function() {
                frappe.confirm('Retire this nominee? This archives the ID and frees the slot.', function() {
                    let old_id = frm.doc.name;
                    let new_id = old_id + '-OLD-' + Math.floor(1000 + Math.random() * 9000);
                    
                    frappe.call({
                        method: 'frappe.model.rename_doc.rename_doc',
                        args: { doctype: frm.doctype, old: old_id, new: new_id, merge: 0 },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.db.set_value('Customer', new_id, 'disabled', 1).then(() => {
                                    frappe.msgprint({ title: 'Success', indicator: 'green', message: 'Nominee Retired!' });
                                    frappe.set_route('Form', 'Customer', new_id);
                                });
                            }
                        }
                    });
                }).addClass('btn-danger');
            });
        }
    }
});

frappe.ui.form.on('Item', {
    refresh: function(frm) {
        apply_pricing_ui_logic(frm);
    },

    item_group: function(frm) {
        apply_pricing_ui_logic(frm);
    },

    custom_is_membership_item: function(frm) {
        if (frm.doc.custom_is_membership_item === 0) {
            frm.set_value('custom_validity_in_years', 0);
            frm.set_value('custom_is_institution', 0);
        }
    },

    custom_is_institution: function(frm) {
        if (frm.doc.custom_is_institution === 0) {
            frm.set_value('custom_allowed_nominees', 0);
        }
    }
});

function apply_pricing_ui_logic(frm) {
    // 1. Define the Groups
    var fnb_groups = ["Food & Beverages", "Restaurant", "Canteen"];

    var liquor_groups = [
        "Liquor", "Beer", "Brandy", "Gin", "Rum", 
        "Vodka", "Whiskey", "Wine"
    ];

    var group = frm.doc.item_group;
    var is_fnb = fnb_groups.includes(group);
    var is_liquor = liquor_groups.includes(group);

    // 2. Standard Rate is now the Default UOM Rate (Bottles for Liquor)
    frm.set_df_property('standard_rate', 'hidden', 0);
    frm.set_df_property('standard_rate', 'label', 'Guest / Standard Rate');

    // 3. LOGIC FOR F&B and LIQUOR
    if (is_fnb || is_liquor) {
        // Hide Tiered Pricing (Member rates are handled via discounts/separate lists)
        frm.set_df_property('custom_railway_member_rate', 'hidden', 1);
        frm.set_df_property('custom_nonrailway_member_rate', 'hidden', 1);

        // Show Smalls Rate ONLY for Liquor
        frm.set_df_property('custom_smalls_rate', 'hidden', is_liquor ? 0 : 1);
    } 

    // 4. LOGIC FOR EVERYTHING ELSE (Sports, Rooms, Memberships)
    else {
        // Show Tiered Pricing for Railway/Non-Railway members
        frm.set_df_property('custom_railway_member_rate', 'hidden', 0);
        frm.set_df_property('custom_nonrailway_member_rate', 'hidden', 0);

        // Hide Smalls Rate
        frm.set_df_property('custom_smalls_rate', 'hidden', 1);
    }
}

frappe.ui.form.on('Subscription', {
    
    // 1. When the form loads (Catches auto-filled IDs from the Customer Dashboard)
    refresh: function(frm) {
        if (frm.doc.party_type === "Customer" && frm.doc.party) {
            // If it's a brand new document but the ID is already there, fetch everything
            if (frm.is_new()) {
                setup_member_details(frm);
            } else {
                // If it's an old, saved document, just ensure the filter is applied
                apply_plan_filter(frm, frm.doc.party);
            }
        }
    },

    // 2. When the clerk manually selects or changes a Member ID
    party: function(frm) {
        if (frm.doc.party_type === "Customer" && frm.doc.party) {
            setup_member_details(frm);
        } else {
            // If the clerk clears the ID field, wipe the form clean
            frm.set_value("custom_member_name", "");
            frm.set_value("custom_subscription_plan", "");
            frm.clear_table("plans");
            frm.refresh_field("plans");
        }
    },

    // 3. When the clerk selects the filtered plan
    custom_subscription_plan: function(frm) {
        if (frm.doc.custom_subscription_plan) {
            frm.clear_table("plans");
            let row = frm.add_child("plans");
            row.plan = frm.doc.custom_subscription_plan;
            row.qty = 1;
            frm.refresh_field("plans");
        }
    }
});

// --- CENTRALIZED LOGIC ---
// This ensures the same actions happen whether auto-filled or manually clicked
function setup_member_details(frm) {
    frappe.db.get_value("Customer", frm.doc.party, ["customer_name", "customer_group"])
        .then(r => {
            if (r && r.message) {
                // 1. Set the Name
                frm.set_value("custom_member_name", r.message.customer_name);
                
                // 2. Wipe the plan ONLY if it's a new document or the ID changed
                frm.set_value("custom_subscription_plan", "");
                frm.clear_table("plans");
                frm.refresh_field("plans");
                
                // 3. Apply the Dropdown Filter instantly
                apply_plan_filter(frm, frm.doc.party, r.message.customer_group);
            }
        });
}

function apply_plan_filter(frm, customer_id, known_group = null) {
    if (!known_group) {
        frappe.db.get_value("Customer", customer_id, "customer_group")
            .then(r => {
                if (r && r.message) {
                    set_the_filter(frm, r.message.customer_group);
                }
            });
    } else {
        set_the_filter(frm, known_group);
    }
}

function set_the_filter(frm, customerGroup) {
    // Instantly filter using the "like" operator on your comma-separated text box
    frm.set_query("custom_subscription_plan", function() {
        return {
            filters: {
                "custom_allowed_customer_groups": ["like", "%" + customerGroup + "%"]
            }
        };
    });
}

frappe.ui.form.on('Subscription', {
    setup: function(frm) {
        // Apply the filter to the 'party' field (the actual Link field)
        frm.set_query('party', function() {
            if (frm.doc.party_type === 'Customer') {
                return {
                    filters: {
                        'customer_group': ['!=', 'Institutional Member']
                    }
                };
            }
        });
    },

    // Trigger validation when the 'party' field changes
    party: function(frm) {
        if (frm.doc.party_type === 'Customer' && frm.doc.party) {
            frappe.db.get_value('Customer', frm.doc.party, 'customer_group').then(r => {
                if (r.message && r.message.customer_group === 'Institutional Member') {
                    frappe.msgprint({
                        title: __('Not Allowed'),
                        indicator: 'red',
                        message: __('Subscriptions cannot be created for the Master Institution. You must create the Subscription for the specific <b>Institutional Nominee</b> instead.')
                    });
                    
                    // Clear the field so they can't save it
                    frm.set_value('party', '');
                }
            });
        }
    }
});

frappe.ui.form.on('Subscription', {
    party: function(frm) {
        if (frm.doc.party_type === 'Customer' && frm.doc.party) {
            // 1. Fetch the Parent Institution from the Customer record
            frappe.db.get_value('Customer', frm.doc.party, 'custom_parent_institution', (r) => {
                if (r && r.custom_parent_institution) {
                    // 2. Set it in your new search field
                    frm.set_value('custom_parent_id', r.custom_parent_institution);
                }
            });
            
            // (Keep your existing validation logic here too...)
            frappe.db.get_value('Customer', frm.doc.party, 'customer_group').then(r => {
                if (r.message && r.message.customer_group === 'Institutional Member') {
                    frappe.msgprint({
                        title: __('Not Allowed'),
                        indicator: 'red',
                        message: __('Subscriptions cannot be created for the Master Institution.')
                    });
                    frm.set_value('party', '');
                    frm.set_value('custom_parent_id', ''); // Clear this too
                }
            });
        }
    }
});

frappe.ui.form.on('Sales Invoice', {
    // 1. RUNS WHEN THE INVOICE LOADS OR SAVES
    refresh: function(frm) {
        apply_guest_logic(frm);
    },

    // 2. RUNS WHEN THE PRICE LIST IS CHANGED
    price_list: function(frm) {
        apply_guest_logic(frm);
    }
});

// REUSABLE LOGIC FUNCTION
function apply_guest_logic(frm) {
    if (frm.doc.price_list === "Standard Selling") {
        // Unhide the fields first
        frm.set_df_property('custom_guest_name', 'hidden', 0);
        frm.set_df_property('custom_guest_contact', 'hidden', 0);

        // Then make them mandatory
        frm.set_df_property('custom_guest_name', 'reqd', 1);
        frm.set_df_property('custom_guest_contact', 'reqd', 1);
    } else {
        // Remove mandatory requirement
        frm.set_df_property('custom_guest_name', 'reqd', 0);
        frm.set_df_property('custom_guest_contact', 'reqd', 0);

        // Hide the fields to keep the form clean for Members
        frm.set_df_property('custom_guest_name', 'hidden', 1);
        frm.set_df_property('custom_guest_contact', 'hidden', 1);
    }
}

frappe.ui.form.on('Bank Account', {
    refresh: function(frm) {
        // --- CSV IMPORT BUTTONS ---
        frm.add_custom_button(__('1. Import Incoming UPI CSV'), function() { upload_and_process(frm, 'upi'); }, __('Import Bank CSV'));
        frm.add_custom_button(__('2. Import Main Statement CSV'), function() { upload_and_process(frm, 'main'); }, __('Import Bank CSV'));

// --- RECONCILIATION BUTTON ---
        frm.add_custom_button(__('3. Run Auto-Reconciliation'), async function() {
            let list = await frappe.db.get_list('Bank Transaction', {
                filters: [
                    ['status', '=', 'Unreconciled'],
                    ['bank_account', '=', frm.doc.name],
                    ['party', '!=', ''] // Fetches ANY linked Supplier, Customer, or Employee
                ],
                fields: ['name', 'party', 'party_type'],
                limit: 1000
            });

            if (!list.length) return frappe.msgprint(__("No pending, party-linked transactions found."));

            frappe.confirm(`Process ${list.length} transactions across all party types?`, async () => {
                let totals = { pos: 0, fifo: 0, mopup: 0, exact: 0 };

                for (let i = 0; i < list.length; i++) {
                    frappe.show_progress(__('Reconciling Ledger'), i + 1, list.length, `Target: ${list[i].party}`);
                    try {
                        let r = await frappe.call({ 
                            method: "trigger_bank_reconciliation", 
                            args: { transaction_name: list[i].name, bank_account: frm.doc.name } 
                        });

                        if (r.message && !r.message.status) { 
                            totals.pos += r.message.pos || 0; 
                            totals.fifo += r.message.fifo || 0; 
                            totals.mopup += r.message.mopup || 0; 
                            totals.exact += r.message.exact_match || 0;

                            // PRINT THE LOG TO THE CONSOLE
                            if (r.message.log) {
                                console.log(`--- TRACE FOR ${list[i].name} ---`);
                                console.log(r.message.log.replace(/<br>/g, '\n').replace(/<\/?b>/g, ''));
                            }
                        }
                    } catch (e) { console.error(e); }
                }
                frappe.hide_progress();
                frappe.msgprint({ 
                    title: __('Sweep Complete'), 
                    indicator: 'green', 
                    message: `Exact Matches: ${totals.exact} | POS: ${totals.pos} | FIFO: ${totals.fifo} | Mop-ups: ${totals.mopup}` 
                });
            });
        }, __('Import Bank CSV')).addClass('btn-primary');    }
});

function upload_and_process(frm, type) {
    let input = document.createElement('input');
    input.type = 'file'; input.accept = '.csv';
    input.onchange = e => {
        let reader = new FileReader();
        reader.readAsText(e.target.files[0], 'UTF-8');
        reader.onload = re => {
            if (type === 'upi') process_upi_csv(re.target.result, frm.doc.name);
            else process_main_csv(re.target.result, frm.doc.name);
        }
    }
    input.click();
}

// ---------------------------------------------------------
// UPI PROCESSOR (NOW WITH AGGRESSIVE DUPLICATE CHECK)
// ---------------------------------------------------------
async function process_upi_csv(csv_text, bank_account) {
    let lines = csv_text.split('\n');
    let report_lines = lines.map(l => l.replace('\r', ''));
    let header_index = -1;
    for (let i = 0; i < report_lines.length; i++) {
        if (report_lines[i].includes("Remitter VPA") || report_lines[i].includes("Beneficiary VPA")) { header_index = i; break; }
    }
    if (header_index === -1) return frappe.msgprint(__("Invalid UPI CSV."));
    report_lines[header_index] += ',"Import_Status","Error_Reason"';

    let tasks = [];
    const months = { 'JAN':'01','FEB':'02','MAR':'03','APR':'04','MAY':'05','JUN':'06','JUL':'07','AUG':'08','SEP':'09','OCT':'10','NOV':'11','DEC':'12'};

    for (let i = header_index + 1; i < report_lines.length; i++) {
        let cols = parseCSVRow(report_lines[i]);
        if (cols.length < 8 || !cols[1]) continue;
        let dm = cols[1].match(/(\d{2})([A-Z]{3})(\d{4})/i);
        if (!dm) continue;
        let formatted_date = `${dm[3]}-${months[dm[2].toUpperCase()]}-${dm[1]}`;
        let vpa = cols[6];
        let party = (vpa && vpa.toLowerCase().startsWith('roc')) ? vpa.split('@')[0].toLowerCase().replace('roc', '').trim() : '';

        tasks.push({
            line_index: i,
            doc: {
                doctype: 'Bank Transaction', date: formatted_date, deposit: parseFloat(cols[8]), 
                reference_number: cols[7], description: `UPI: ${cols[3]} (${cols[2]})`,
                bank_account: bank_account, party_type: party ? 'Customer' : '', party: party
            }
        });
    }

    frappe.confirm(`Import ${tasks.length} UPI rows?`, async () => {
        for (let t of tasks) {
            frappe.show_progress(__('Importing UPI'), tasks.indexOf(t) + 1, tasks.length);
            let status = "Success", reason = "";

            // --- NEW: UTR CHECK FOR UPI STATEMENT ---
            let exists = await frappe.db.get_list('Bank Transaction', { filters: { reference_number: t.doc.reference_number }, limit: 1 });
            if (exists.length) { 
                status = "Skipped"; reason = "Duplicate Reference (Already in ERPNext)"; 
            } else {
                try {
                    let res = await frappe.call({ method: 'frappe.client.insert', args: { doc: t.doc } });
                    reason = "Created: " + res.message.name;
                } catch (e) { 
                    if (t.doc.party) {
                        t.doc.party = ""; t.doc.party_type = "";
                        let res = await frappe.call({ method: 'frappe.client.insert', args: { doc: t.doc } });
                        status = "Linked (No ID)"; reason = "Member ID not found.";
                    } else { status = "Failed"; reason = "API Error"; }
                }
            }
            report_lines[t.line_index] += `,"${status}","${reason}"`;
        }
        frappe.hide_progress();
        downloadAnnotatedRawCSV(report_lines, 'UPI_Audit');
    });
}

// ---------------------------------------------------------
// MAIN STATEMENT PROCESSOR (Checks Reference against UPI)
// ---------------------------------------------------------
async function process_main_csv(csv_text, bank_account) {
    let lines = csv_text.split('\n');
    let report_lines = lines.map(l => l.replace('\r', ''));
    let header_index = -1;
    for (let i = 0; i < report_lines.length; i++) {
        if (report_lines[i].includes('Sl. No.') && report_lines[i].includes('Tran Date')) { header_index = i; break; }
    }
    if (header_index === -1) return frappe.msgprint(__("Invalid Main CSV."));
    report_lines[header_index] += ',"Import_Status","Error_Reason"';

    let tasks = [];
    for (let i = header_index + 1; i < report_lines.length; i++) {
        let cols = parseCSVRow(report_lines[i]);
        if (cols.length < 9 || !cols[1].includes('/')) continue;
        let d = cols[1].split('/');
        let particulars = cols[2];
        let ref_num = particulars.includes("UPI") ? (particulars.split('/')[1] || "").trim() : (particulars.includes("IMPS") ? (particulars.split('/')[2] || "").trim() : "");

        tasks.push({
            line_index: i,
            doc: {
                doctype: 'Bank Transaction', date: `${d[2]}-${d[1]}-${d[0]}`, 
                deposit: parseFloat(cols[8]) || 0, withdrawal: parseFloat(cols[7]) || 0,
                description: particulars, bank_account: bank_account, reference_number: ref_num
            }
        });
    }

    frappe.confirm(`Import ${tasks.length} Main Statement entries?`, async () => {
        for (let t of tasks) {
            frappe.show_progress(__('Importing Main'), tasks.indexOf(t) + 1, tasks.length);
            let status = "Success", reason = "";

            // --- UTR CHECK FOR MAIN STATEMENT ---
            let filters = (t.doc.reference_number && t.doc.reference_number.length >= 10) ? { reference_number: t.doc.reference_number } : { description: t.doc.description, date: t.doc.date, deposit: t.doc.deposit };

            let exists = await frappe.db.get_list('Bank Transaction', { filters: filters, limit: 1 });
            if (exists.length) { 
                status = "Skipped"; reason = "Duplicate Reference (Already in ERPNext)"; 
            } else {
                try {
                    let res = await frappe.call({ method: 'frappe.client.insert', args: { doc: t.doc } });
                    reason = "Created: " + res.message.name;
                } catch (e) { status = "Failed"; reason = "API Error"; }
            }
            report_lines[t.line_index] += `,"${status}","${reason}"`;
        }
        frappe.hide_progress();
        downloadAnnotatedRawCSV(report_lines, 'Main_Audit');
    });
}

function parseCSVRow(str) {
    let res = [], inside = false, word = '';
    for (let i = 0; i < str.length; i++) {
        let c = str[i];
        if (c === '"') inside = !inside;
        else if (c === ',' && !inside) { res.push(word.trim()); word = ''; }
        else word += c;
    }
    res.push(word.trim()); return res;
}

function downloadAnnotatedRawCSV(report_lines, type) {
    const blob = new Blob([report_lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = window.URL.createObjectURL(blob);
    link.download = `${type}_${frappe.datetime.now_datetime()}.csv`;
    link.click();
}

