frappe.ui.form.on('Purchase Invoice', {
    refresh: function(frm) {
        frm.trigger('lock_item_dropdown');
    },
    supplier: function(frm) {
        frm.trigger('lock_item_dropdown');
    },
    filter_items_by_supplier: function(frm) {
        frm.trigger('lock_item_dropdown');
    },

    lock_item_dropdown: function(frm) {
        let apply_filter = frm.doc.filter_items_by_supplier === 1;

        // Scenario A: Filter is ON and Supplier is selected
        if (apply_filter && frm.doc.supplier) {
            
            // SECURITY BYPASS: Query the main 'Item' table instead of the restricted child table
            frappe.db.get_list('Item', {
                filters: [
                    // Advanced nested filter: Look for the supplier inside the child table
                    ['Item Supplier', 'supplier', '=', frm.doc.supplier],
                    ['is_purchase_item', '=', 1]
                ],
                fields: ['name'],
                limit: 500
            }).then(records => {
                let valid_items = records.map(r => r.name);

                if (valid_items.length === 0) {
                    valid_items = ['--NO-LINKED-ITEMS-FOUND--'];
                }

                // Lock the dropdown using the confirmed list
                frm.set_query("item_code", "items", function() {
                    return { filters: { 'name': ['in', valid_items] } };
                });
            });
        } 
        // Scenario B: Filter is OFF or No Supplier
        else {
            frm.set_query("item_code", "items", function() {
                return { filters: { 'is_purchase_item': 1 } };
            });
        }
    }
});

frappe.ui.form.on('Bank Transaction', {
    refresh: function(frm) {
        frm.remove_custom_button(__('Create Match Rule'));

        // Show button if transaction is unlinked and submitted
        if (!frm.doc.party && frm.doc.docstatus === 1) {

            frm.add_custom_button(__('Create Match Rule'), function() {
                let full_description = frm.doc.description ? frm.doc.description.trim() : '';

                frappe.prompt([
                    {
                        label: __('Full Bank Narrative'),
                        fieldname: 'bank_desc',
                        fieldtype: 'Small Text',
                        default: full_description,
                        read_only: 1
                    },
                    {
                        label: __('Target Match Keyword'),
                        fieldname: 'keyword',
                        fieldtype: 'Data',
                        default: full_description,
                        reqd: 1
                    },
                    {
                        label: __('Party Type'),
                        fieldname: 'party_type',
                        fieldtype: 'Select',
                        options: ['Supplier', 'Customer', 'Employee'],
                        default: 'Supplier',
                        reqd: 1
                    },
                    {
                        label: __('Party'),
                        fieldname: 'party',
                        fieldtype: 'Dynamic Link',
                        options: 'party_type',
                        reqd: 1
                    }
                ], function(values) {

                    // 1. Create the Bank Match Rule document in the background
                    frappe.db.insert({
                        doctype: 'Bank Match Rule',
                        keyword: values.keyword.trim(),
                        party_type: values.party_type,
                        party: values.party
                    }).then(inserted_doc => {
                        frappe.show_alert({
                            message: __('Match Rule "{0}" created successfully', [values.keyword]),
                            indicator: 'green'
                        });

                        // 2. Update ONLY the allowed clearing fields on the submitted Bank Transaction
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'Bank Transaction',
                                name: frm.doc.name,
                                fieldname: {
                                    'party_type': values.party_type,
                                    'party': values.party
                                }
                            },
                            callback: function(r) {
                                if(!r.exc) {
                                    frm.reload_doc();
                                    frappe.show_alert({
                                        message: __('Bank Transaction linked to {0}', [values.party]),
                                        indicator: 'green'
                                    });
                                }
                            }
                        });
                    }).catch(err => {
                        frappe.msgprint(__('Could not create rule. Check if keyword rule already exists.'));
                    });

                }, __('Create Rule & Link Transaction'), __('Create & Link'));

            });

            frm.change_custom_button_type(__('Create Match Rule'), null, 'primary');
        }
    }
});
